import { useEffect, useState } from "react";

export default function StreakCalendar() {
  const [data, setData] = useState({});

  useEffect(() => {
    const weeklyData = JSON.parse(localStorage.getItem("weeklyProgress") || "{}");
    setData(weeklyData);
  }, []);

  const days = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

  const getColor = (value) => {
    if (value === 0) return "bg-slate-700";
    if (value === 1) return "bg-blue-400";
    if (value === 2) return "bg-blue-500";
    if (value === 3) return "bg-blue-600";
    return "bg-blue-700";
  };

  return (
    <div className="space-y-3">

      {/* Labels */}
      <div className="grid grid-cols-7 text-xs text-slate-400">
        {days.map((d) => (
          <span key={d}>{d}</span>
        ))}
      </div>

      {/* Calendar Boxes */}
      <div className="grid grid-cols-7 gap-2">
        {days.map((_, i) => {
          const value = data[i + 1] || 0;

          return (
            <div
              key={i}
              className={`h-10 rounded-lg ${getColor(value)} transition-all duration-700 hover:scale-110`}
              title={`${value} tasks completed`}
            />
          );
        })}
      </div>

    </div>
  );
}
